-- Neon migration for feature 30j: the new Gold tables. Generated by
-- python neon_publish/main.py --print-migration 30j; review and coordinate the web app
-- before applying. Run as one transaction on the direct Neon connection. The
-- recurring publisher never executes this file.
BEGIN;
SET LOCAL lock_timeout = '15s';

CREATE TABLE public.app_game_player_on_court (
    "competition_code" TEXT NOT NULL,
    "season_code" TEXT NOT NULL,
    "game_code" INTEGER NOT NULL,
    "side" TEXT NOT NULL,
    "person_key" TEXT NOT NULL,
    "interval_ordinal" INTEGER NOT NULL,
    "club_code" TEXT,
    "start_seconds" INTEGER,
    "end_seconds" INTEGER,
    PRIMARY KEY (competition_code, season_code, game_code, side, person_key, interval_ordinal)
);

CREATE TABLE public.app_game_team_lineup_stints (
    "competition_code" TEXT NOT NULL,
    "season_code" TEXT NOT NULL,
    "game_code" INTEGER NOT NULL,
    "side" TEXT NOT NULL,
    "stint_ordinal" INTEGER NOT NULL,
    "club_code" TEXT,
    "opponent_club_code" TEXT,
    "start_seconds" INTEGER,
    "end_seconds" INTEGER,
    "players" TEXT,
    "opponent_players" TEXT,
    "possessions_for" INTEGER,
    "possessions_against" INTEGER,
    "points_for" INTEGER,
    "points_against" INTEGER,
    PRIMARY KEY (competition_code, season_code, game_code, side, stint_ordinal)
);

CREATE TABLE public.app_game_stat_gaps (
    "competition_code" TEXT NOT NULL,
    "season_code" TEXT NOT NULL,
    "game_code" INTEGER NOT NULL,
    "stat_name" TEXT NOT NULL,
    "reason" TEXT,
    PRIMARY KEY (competition_code, season_code, game_code, stat_name)
);

COMMIT;
